export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function identify(root){root.querySelectorAll('h1,h2,h3,h4,p,img,a.btn,button[data-quote],.counter-item b,.counter-item span,.eyebrow').forEach((el,i)=>{if(!el.hasAttribute('data-cms-id'))el.dataset.cmsId='e'+i;});const parent=root.querySelector('.page-enter');if(parent)[...parent.children].forEach((el,i)=>{if(!el.dataset.cmsSection)el.dataset.cmsSection='s'+i;});}
export function styleText(s={}){return Object.entries(s).map(([k,v])=>({fontSize:'font-size:'+v+'px',color:'color:'+v,backgroundColor:'background-color:'+v,textAlign:'text-align:'+v,fontWeight:'font-weight:'+v,fontFamily:'font-family:'+v,width:'width:'+v+'%',height:'height:'+v+'px',borderRadius:'border-radius:'+v+'px',objectFit:'object-fit:'+v,objectPosition:'object-position:'+v+'% center',padding:'padding:'+v+'px',opacity:'opacity:'+v}[k]||'')).filter(Boolean).join(';');}
export function blockHTML(b){return `<section class="cms-added-section" data-cms-section="${esc(b.id)}" style="${esc(styleText(b.style))}"><div class="wrap" style="display:grid;gap:24px;grid-template-columns:${b.kind==='text-image'?'repeat(auto-fit,minmax(min(100%,300px),1fr))':'1fr'};align-items:center">${b.kind!=='image'?`<div><h2 data-cms-id="${b.id}-title">${esc(b.title)}</h2><p data-cms-id="${b.id}-body" style="white-space:pre-line">${esc(b.body)}</p>${b.link?`<a class="btn" href="${esc(b.link)}">${esc(b.button||'Learn more')}</a>`:''}</div>`:''}${b.kind!=='text'&&b.image?`<img data-cms-id="${b.id}-image" src="${esc(b.image)}" alt="${esc(b.alt)}" loading="lazy" style="width:100%;height:auto;border-radius:16px">`:''}</div></section>`;}
export function apply(root,c,{seo=true}={}){identify(root);const doc=root.ownerDocument;root.querySelectorAll('.cms-added-section').forEach(el=>el.remove());const parent=root.querySelector('.page-enter');for(const b of c.blocks||[])parent?.insertAdjacentHTML('beforeend',blockHTML(b));for(const e of c.edits||[]){let el;try{el=root.querySelector(e.selector.replace(/^#main\s*/,''))||doc.querySelector(e.selector);}catch{continue;}if(!el)continue;if(e.type==='text'&&typeof e.value==='string'){el.textContent=e.value;el.removeAttribute('data-count');}if(e.type==='image'&&el.tagName==='IMG'){el.removeAttribute('srcset');el.closest('picture')?.querySelectorAll('source').forEach(s=>s.remove());el.src=e.value;if(e.alt!==undefined)el.alt=e.alt;}if(e.style){el.style.cssText+=';'+styleText(e.style);if(e.type==='image'&&e.style.height===undefined)el.style.height='auto';}if(e.link!==undefined){const a=el.closest('a');if(a)a.href=e.link;}if(e.hidden)el.hidden=true;}
 const old=doc.getElementById('cms-responsive');old?.remove();const mobile=(c.edits||[]).filter(e=>e.mobile&&Object.keys(e.mobile).length).map(e=>`${e.selector}{${styleText(e.mobile).split(';').filter(Boolean).map(d=>d+'!important').join(';')}}`).join('');if(mobile){const st=doc.createElement('style');st.id='cms-responsive';st.textContent='@media(max-width:700px){'+mobile.replace(/;(?![^{}]*\})/g,';')+'}';doc.head.append(st);}
 if(parent){if(c.sectionOrder?.length)for(const id of c.sectionOrder){const n=[...parent.children].find(el=>el.dataset.cmsSection===id);if(n)parent.append(n);}else if(c.order?.length){const ns=[...parent.children];if(c.order.length===ns.length)c.order.forEach(i=>ns[i]&&parent.append(ns[i]));}}
 for(const s of c.sections||[]){const el=root.querySelector(`[data-cms-section="${s.id}"]`);if(el){el.style.cssText+=';'+styleText(s.style);el.hidden=!!s.hidden;}}
 if(seo&&c.seo){if(c.seo.title)doc.title=c.seo.title;for(const [name,v] of [['description',c.seo.description],['robots',c.seo.noindex===undefined?'':c.seo.noindex?'noindex,follow':'index,follow']])if(v)doc.querySelector(`meta[name="${name}"]`)?.setAttribute('content',v);for(const p of ['og:title','twitter:title'])if(c.seo.title)doc.querySelector(`meta[property="${p}"],meta[name="${p}"]`)?.setAttribute('content',c.seo.title);for(const p of ['og:description','twitter:description'])if(c.seo.description)doc.querySelector(`meta[property="${p}"],meta[name="${p}"]`)?.setAttribute('content',c.seo.description);}
}